//! Generated ML model weights consumed by the XGBoost / MLP policies.
//!
//! Two sources for each model:
//!
//! - **Stub** (always compiled): a placeholder `*_predict` function that
//!   returns 0.5. Lets M3 (classical policies) and the trait layer
//!   compile + link without the real weights. The stub is what ships
//!   when `ai_eviction_models` is OFF.
//! - **Real** (gated on `ai_eviction_models`): the ~1.3 MB XGBoost
//!   if-else chain and the int8-quantized MLP weights, generated by
//!   the sibling `slm-os-page-sim` project and imported via
//!   `scripts/import_eviction_weights.sh`.
//!
//! The two file sets share a public API — `xgb_predict(&[f32; 27]) -> f32`
//! and `mlp_predict(&[f32; 27]) -> f32` — so M4's `xgboost.rs` /
//! `mlp.rs` don't need to know which is linked in.

// XGBoost
#[cfg(not(feature = "ai_eviction_models"))]
mod xgb_stub;
#[cfg(not(feature = "ai_eviction_models"))]
pub use xgb_stub::xgb_predict;

#[cfg(feature = "ai_eviction_models")]
mod xgb_policy_generated;
#[cfg(feature = "ai_eviction_models")]
pub use xgb_policy_generated::xgb_predict;

// MLP (int8)
#[cfg(not(feature = "ai_eviction_models"))]
mod mlp_stub;
#[cfg(not(feature = "ai_eviction_models"))]
pub use mlp_stub::mlp_predict;

#[cfg(feature = "ai_eviction_models")]
mod mlp_policy_generated;
#[cfg(feature = "ai_eviction_models")]
pub use mlp_policy_generated::mlp_predict;

// Float32 MLP (cross-check reference). Available whenever
// `ai_eviction_models` is on; consumed by the int8-vs-f32 agreement
// check in `lib::rust_eviction_run_tests`. Not used in the hot path.
#[cfg(feature = "ai_eviction_models")]
pub mod mlp_policy_f32;

#[cfg(feature = "ai_eviction_models")]
pub use mlp_policy_f32::mlp_predict_f32;

/// `true` when the generated model files are linked in, `false` when
/// the stub is active. Runtime code can use this to decide whether to
/// fall back to classical policies.
pub const MODELS_AVAILABLE: bool = cfg!(feature = "ai_eviction_models");
